using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiFetchTool
{
    [McpServerTool, Description("Fetches a post by ID from an external API.")]
    public static async Task<string> FetchPost(
        IHttpClientFactory httpClientFactory,
        ILogger<McpServer> logger,
        [Description("The numeric post ID to retrieve.")] int id)
    {
        logger.LogInformation("Fetching post {Id}", id);

        var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync($"posts/{id}");
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        return json.ToString();
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt that asks for a concise summary of the given text.")]
    public static IList<Microsoft.Extensions.AI.ChatMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional maximum number of sentences.")] string? maxSentences = null)
    {
        var constraint = maxSentences is not null
            ? $" Use at most {maxSentences} sentences."
            : string.Empty;

        return
        [
            new(Microsoft.Extensions.AI.ChatRole.User,
                $"Please provide a concise summary of the following text.{constraint}\n\n{text}")
        ];
    }
}

